CREATE TABLE IF NOT EXISTS emails (id TEXT PRIMARY KEY, subject TEXT NOT NULL DEFAULT '', recipient TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS links (id TEXT PRIMARY KEY, email_id TEXT NOT NULL REFERENCES emails(id) ON DELETE CASCADE, original_url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, email_id TEXT NOT NULL REFERENCES emails(id) ON DELETE CASCADE, link_id TEXT REFERENCES links(id) ON DELETE CASCADE, event_type TEXT NOT NULL CHECK(event_type IN ('open','click')), timestamp TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, user_agent TEXT, country TEXT);
CREATE TABLE IF NOT EXISTS ignored_ips (ip TEXT PRIMARY KEY, label TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_events_email ON events(email_id);
CREATE INDEX IF NOT EXISTS idx_events_timestamp ON events(timestamp);
CREATE INDEX IF NOT EXISTS idx_links_email ON links(email_id);
